sparql_constraint_test_map.query:
PREFIX zg: <urn:zombie-game:v0.1:>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
SELECT $this WHERE {
$this zg:actorStart ?s; zg:actionDefinition ?d. ?s zg:life ?l; zg:actionStatus ?as; zg:stamina ?st. ?d zg:stamina_cost ?cost. FILTER(?l<=0 || ?as!=zg:IDLE || ?st<?cost)
}

PREFIX zg: <urn:zombie-game:v0.1:>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
SELECT $this WHERE {
$this zg:actorStart ?s; zg:actionDefinition/zg:capability ?cap. FILTER(NOT EXISTS {?s zg:hasTypeProfile/zg:grants ?cap} && NOT EXISTS {?s zg:activeRole/zg:roleDefinition/zg:grants ?cap})
}

PREFIX zg: <urn:zombie-game:v0.1:>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
SELECT $this WHERE {
$this zg:actionResult ?r; zg:actionDefinition ?d; zg:resolvedAt ?t; zg:actorStart/zg:biologicalType ?old; zg:actorAfterEnd ?s. ?d zg:cooldown ?cd. ?s zg:life ?l; zg:biologicalType ?new. FILTER(?r!=zg:IN_PROGRESS && ?l>0 && ?old=?new && ?cd>0) FILTER(NOT EXISTS {?s zg:cooldownRecord [zg:forAction ?d; zg:until ?u] FILTER(?u=?t+?cd)})
}

PREFIX zg: <urn:zombie-game:v0.1:>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
SELECT $this WHERE {
$this zg:startTime ?t; zg:plannedEnd ?e; zg:actionDefinition ?a. ?a zg:duration_min ?lo; zg:duration_max ?hi. FILTER(?e-?t<?lo || ?e-?t>?hi)
}

PREFIX zg: <urn:zombie-game:v0.1:>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
SELECT $this WHERE {
$this zg:actionResult ?r; zg:actorAfterEnd ?s. FILTER(?r!=zg:IN_PROGRESS) ?s zg:activeAction ?a.
}

PREFIX zg: <urn:zombie-game:v0.1:>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
SELECT $this WHERE {
$this zg:life ?l; zg:actionStatus ?s. FILTER((?l=0 && ?s!=zg:ACTION_DEAD) || (?l>0 && ?s=zg:ACTION_DEAD) || (?s=zg:BUSY && NOT EXISTS {$this zg:activeAction ?a}) || (?s!=zg:BUSY && EXISTS {$this zg:activeAction ?a}))
}

PREFIX zg: <urn:zombie-game:v0.1:>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
SELECT $this WHERE {
$this zg:actorStart/zg:ofAgent ?x; zg:actorBeforeEnd ?b; zg:actorAfterEnd ?a; zg:resolvedAt ?t. ?b zg:ofAgent ?y; zg:atTime ?bt; zg:revision ?br. ?a zg:ofAgent ?z; zg:atTime ?at; zg:revision ?ar. FILTER(?x!=?y || ?x!=?z || ?bt!=?t || ?at!=?t || ?ar<=?br)
}

PREFIX zg: <urn:zombie-game:v0.1:>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
SELECT $this WHERE {
$this zg:actionResult ?r; zg:actorBeforeEnd/zg:life ?l. FILTER(?r IN (zg:SUCCEEDED,zg:MISSED) && ?l<=0)
}

PREFIX zg: <urn:zombie-game:v0.1:>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
SELECT $this WHERE {
$this zg:actorStart ?b; zg:actorAfterStart ?a; zg:startTime ?t. ?b zg:ofAgent ?x; zg:atTime ?bt; zg:revision ?br. ?a zg:ofAgent ?y; zg:atTime ?at; zg:revision ?ar. FILTER(?x!=?y || ?bt!=?t || ?at!=?t || ?ar<=?br || NOT EXISTS {?a zg:activeAction $this; zg:actionStatus zg:BUSY})
}

PREFIX zg: <urn:zombie-game:v0.1:>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
SELECT $this WHERE {
$this zg:startTime ?t; zg:actionDefinition ?d; zg:actorStart/zg:cooldownRecord ?c. ?c zg:forAction ?d; zg:until ?u. FILTER(?t<?u)
}

PREFIX zg: <urn:zombie-game:v0.1:>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
SELECT $this WHERE {
$this zg:actorStart ?b; zg:actorAfterStart ?a; zg:actionDefinition/zg:stamina_cost ?cost. ?b zg:stamina ?s. ?a zg:stamina ?v. FILTER(?v!=?s-?cost)
}

PREFIX zg: <urn:zombie-game:v0.1:>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
SELECT $this WHERE {
$this zg:actionResult ?result; zg:actorBeforeEnd ?a; zg:targetBeforeEnd ?b; zg:actionDefinition/zg:reach ?r. FILTER(?result IN (zg:SUCCEEDED,zg:MISSED)) ?a zg:x ?x; zg:y ?y. ?b zg:x ?u; zg:y ?v. FILTER((?x-?u)*(?x-?u)+(?y-?v)*(?y-?v)>?r*?r)
}

PREFIX zg: <urn:zombie-game:v0.1:>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
SELECT $this WHERE {
$this zg:actorStart ?a; zg:targetStart ?b; zg:actionDefinition/zg:reach ?r. ?a zg:x ?x; zg:y ?y. ?b zg:x ?u; zg:y ?v. FILTER((?x-?u)*(?x-?u)+(?y-?v)*(?y-?v)>?r*?r)
}

PREFIX zg: <urn:zombie-game:v0.1:>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
SELECT $this WHERE {
$this zg:life ?l; zg:biologicalType ?t. FILTER(?l>0 && (NOT EXISTS {$this zg:activeModel ?m} || NOT EXISTS {$this zg:hasTypeProfile ?t}))
}

PREFIX zg: <urn:zombie-game:v0.1:>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
SELECT $this WHERE {
$this zg:integrity ?i; zg:max_integrity ?m. FILTER(?i>?m)
}

PREFIX zg: <urn:zombie-game:v0.1:>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
SELECT $this WHERE {
$this zg:biomass ?b; zg:reserved_biomass ?r. FILTER(?r>?b)
}

PREFIX zg: <urn:zombie-game:v0.1:>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
SELECT $this WHERE {
$this zg:episode ?e; zg:beforeState ?b; zg:afterState ?a. ?b zg:activeEpisode ?be. ?a zg:atTime ?t; zg:revision ?r. ?e zg:conversion_due_at ?due; zg:episodeOutcome ?out; zg:ended_at ?end; zg:end_revision ?er. FILTER(?be!=?e || ?t!=?due || ?out!=zg:CONVERTED || ?end!=?t || ?er!=?r)
}

PREFIX zg: <urn:zombie-game:v0.1:>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
SELECT $this WHERE {
$this zg:beforeState ?b; zg:afterState ?a. ?b zg:life ?l; zg:stamina ?s; zg:x ?x; zg:y ?y. ?a zg:life ?m; zg:stamina ?t; zg:x ?u; zg:y ?v. FILTER(?l!=?m || ?s!=?t || ?x!=?u || ?y!=?v)
}

PREFIX zg: <urn:zombie-game:v0.1:>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
SELECT $this WHERE {
$this zg:beforeState ?b; zg:afterState ?a. ?b zg:biologicalType ?bt; zg:status ?bs; zg:life ?bl. ?a zg:biologicalType ?at; zg:status ?as. FILTER(?bt!=zg:Human || ?bs!=zg:INFECTED || ?bl<=0 || ?at!=zg:Zombie || ?as!=zg:ACTIVE || EXISTS {?a zg:activeRole ?r} || EXISTS {?a zg:inventory ?i})
}

PREFIX zg: <urn:zombie-game:v0.1:>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
SELECT $this WHERE {
$this zg:episode ?e; zg:beforeState ?b; zg:afterState ?a; zg:triggeredBy ?act. ?b zg:activeEpisode ?old. ?a zg:atTime ?t; zg:revision ?r. ?e zg:conversion_due_at ?due; zg:episodeOutcome ?out; zg:ended_at ?end; zg:end_revision ?er. FILTER(?old!=?e || ?t>=?due || ?out!=zg:CURED || ?end!=?t || ?er!=?r || NOT EXISTS {?act zg:actionDefinition zg:action_treat_infection; zg:actionResult zg:SUCCEEDED; zg:targetBeforeEnd ?b; zg:targetAfterEnd ?a})
}

PREFIX zg: <urn:zombie-game:v0.1:>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
SELECT $this WHERE {
$this zg:beforeState ?b; zg:afterState ?a. ?b zg:status ?bs; zg:biologicalType ?bt; zg:life ?l. ?a zg:status ?as; zg:biologicalType ?at; zg:life ?v. FILTER(?bs!=zg:INFECTED || ?as!=zg:HEALTHY || ?bt!=zg:Human || ?at!=zg:Human || ?l<=0 || ?v!=?l)
}

PREFIX zg: <urn:zombie-game:v0.1:>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
SELECT $this WHERE {
$this zg:life 0. FILTER(EXISTS {$this zg:activeRole ?r} || EXISTS {$this zg:activeModel ?m} || EXISTS {$this zg:activeAction ?a} || EXISTS {$this zg:activeEpisode ?e} || EXISTS {$this zg:hasTypeProfile ?t} || EXISTS {$this zg:effect ?f} || EXISTS {$this zg:cooldownRecord ?c} || EXISTS {$this zg:speed ?s FILTER(?s!=0)} || EXISTS {$this zg:sense_r ?r FILTER(?r!=0)} || NOT EXISTS {$this zg:death_at ?d; zg:deathCause ?c})
}

PREFIX zg: <urn:zombie-game:v0.1:>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
SELECT $this WHERE {
$this zg:life 0; zg:inventory/zg:stock/zg:quantity ?q. FILTER(?q!=0)
}

PREFIX zg: <urn:zombie-game:v0.1:>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
SELECT $this WHERE {
$this zg:beforeState ?b; zg:afterState ?a. ?b zg:life ?l; zg:biologicalType ?ty; zg:x ?x; zg:y ?y. ?a zg:life ?v; zg:status ?s; zg:biologicalType ?at; zg:x ?u; zg:y ?w. FILTER(?l<=0 || ?v!=0 || ?s!=zg:DEAD || ?ty!=?at || ?x!=?u || ?y!=?w)
}

PREFIX zg: <urn:zombie-game:v0.1:>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
SELECT $this WHERE {
$this zg:duration_min ?a; zg:duration_max ?b. FILTER(?a>?b)
}

PREFIX zg: <urn:zombie-game:v0.1:>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
SELECT $this WHERE {
$this zg:episodeOutcome ?o. FILTER((?o=zg:ONGOING && (EXISTS {$this zg:ended_at ?e} || EXISTS {$this zg:end_revision ?r})) || (?o!=zg:ONGOING && NOT EXISTS {$this zg:ended_at ?e; zg:end_revision ?r}))
}

PREFIX zg: <urn:zombie-game:v0.1:>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
SELECT $this WHERE {
$this zg:onset_at ?o; zg:incubation_duration ?d; zg:conversion_due_at ?t. FILTER(?t != ?o+?d)
}

PREFIX zg: <urn:zombie-game:v0.1:>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
SELECT $this WHERE {
$this zg:onset_at ?o; zg:onset_revision ?r; zg:ended_at ?e; zg:end_revision ?v. FILTER(?e<?o || (?e=?o && ?v<?r))
}

PREFIX zg: <urn:zombie-game:v0.1:>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
SELECT $this WHERE {
$this zg:ofAgent ?a; zg:atTime ?t; zg:revision ?r; zg:activeEpisode ?e. ?e zg:infectedAgent ?b; zg:onset_at ?on; zg:onset_revision ?orr; zg:conversion_due_at ?due. OPTIONAL {?e zg:ended_at ?end; zg:end_revision ?er} FILTER(?a!=?b || ?t<?on || (?t=?on && ?r<?orr) || ?t>?due || (BOUND(?end) && (?t>?end || (?t=?end && ?r>=?er))))
}

PREFIX zg: <urn:zombie-game:v0.1:>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
SELECT $this WHERE {
$this zg:gateMode ?g; zg:integrity ?i. FILTER((?g=zg:BREACHED && ?i!=0) || (?g!=zg:BREACHED && ?i=0))
}

PREFIX zg: <urn:zombie-game:v0.1:>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
SELECT $this WHERE {
$this zg:integrity ?i; zg:max_integrity ?m. FILTER(?i>?m)
}

PREFIX zg: <urn:zombie-game:v0.1:>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
SELECT $this WHERE {
$this zg:infection_progress ?p; zg:atTime ?t. OPTIONAL {$this zg:activeEpisode ?e. ?e zg:onset_at ?o; zg:incubation_duration ?d} FILTER((!BOUND(?e) && ?p!=0) || (BOUND(?e) && ABS(?p - ((?t-?o)/?d))>0.000000001))
}

PREFIX zg: <urn:zombie-game:v0.1:>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
SELECT $this WHERE {
$this zg:realizes ?i; zg:actorStart/zg:ofAgent ?a; zg:actionDefinition ?d; zg:startTime ?s. ?i zg:actor ?b; zg:actionDefinition ?e; zg:proposedAt ?p; zg:observes/zg:observer ?o. FILTER(?a!=?b || ?d!=?e || ?s<?p || ?a!=?o)
}

PREFIX zg: <urn:zombie-game:v0.1:>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
SELECT $this WHERE {
$this zg:inventory/zg:stock/zg:quantity ?q; zg:carry_capacity ?c.
} GROUP BY $this HAVING(SUM(?q)>MAX(?c))

PREFIX zg: <urn:zombie-game:v0.1:>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
SELECT $this WHERE {
$this zg:life ?l. FILTER(?l>0 && (EXISTS {$this zg:death_at ?d} || EXISTS {$this zg:deathCause ?c}))
}

PREFIX zg: <urn:zombie-game:v0.1:>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
SELECT $this WHERE {
$this zg:actionResult zg:MISSED; zg:actionDefinition ?d. FILTER(?d NOT IN (zg:action_melee,zg:action_claw,zg:action_bite,zg:action_power_strike,zg:action_spit))
}

PREFIX zg: <urn:zombie-game:v0.1:>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
SELECT $this WHERE {
$this zg:start_at ?s; zg:end_at ?e. FILTER(?e<?s)
}

PREFIX zg: <urn:zombie-game:v0.1:>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
SELECT $this WHERE {
$this zg:ofAgent ?a; zg:activeModel/zg:ofAgent ?b. FILTER(?a!=?b)
}

PREFIX zg: <urn:zombie-game:v0.1:>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
SELECT $this WHERE {
$this zg:cause+ $this.
}

PREFIX zg: <urn:zombie-game:v0.1:>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
SELECT $this WHERE {
$this zg:life 0; zg:ofAgent ?a; zg:atTime ?t; zg:revision ?r; zg:biologicalType ?ty; zg:x ?x; zg:y ?y. ?later a zg:AgentState; zg:ofAgent ?a; zg:atTime ?u; zg:revision ?v; zg:life ?l; zg:biologicalType ?lt; zg:x ?lx; zg:y ?ly. FILTER((?u>?t || (?u=?t && ?v>?r)) && (?l!=0 || ?ty!=?lt || ?x!=?lx || ?y!=?ly))
}

PREFIX zg: <urn:zombie-game:v0.1:>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
SELECT $this WHERE {
$this zg:observer ?a; zg:selfState ?s; zg:atTime ?t; zg:revision ?r. ?s zg:ofAgent ?b; zg:atTime ?u; zg:revision ?v. FILTER(?a!=?b || ?t!=?u || ?r!=?v)
}

PREFIX zg: <urn:zombie-game:v0.1:>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
SELECT $this WHERE {
$this zg:actorStart/zg:ofAgent ?actor; zg:startTime ?s; zg:plannedEnd ?p. OPTIONAL {$this zg:resolvedAt ?r} BIND(COALESCE(?r,?p) AS ?end) ?other a zg:ActionOccurrence; zg:actorStart/zg:ofAgent ?actor; zg:startTime ?os; zg:plannedEnd ?op. OPTIONAL {?other zg:resolvedAt ?orr} BIND(COALESCE(?orr,?op) AS ?oe) FILTER(?other!=$this && ?s<?oe && ?os<?end)
}

PREFIX zg: <urn:zombie-game:v0.1:>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
SELECT $this WHERE {
$this zg:x ?x; zg:y ?y; zg:world ?w. ?w zg:length ?l; zg:width ?h. FILTER(?x<0 || ?y<0 || ?x>?l || ?y>?h)
}

PREFIX zg: <urn:zombie-game:v0.1:>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
SELECT $this WHERE {
$this zg:actionDefinition/zg:mayCause zg:PhysicalDamageEffect; zg:actionResult ?r; zg:actorStart/zg:ofAgent ?actor; zg:targetStart/zg:ofAgent ?target; zg:startTime ?s; zg:resolvedAt ?end. ?other a zg:ActionOccurrence; zg:actionDefinition/zg:mayCause zg:PhysicalDamageEffect; zg:actionResult ?orr; zg:actorStart/zg:ofAgent ?target; zg:targetStart/zg:ofAgent ?actor; zg:startTime ?os; zg:resolvedAt ?oe. FILTER(?other!=$this && ?r IN (zg:SUCCEEDED,zg:MISSED) && ?orr IN (zg:SUCCEEDED,zg:MISSED) && ?s<?oe && ?os<?end)
}

PREFIX zg: <urn:zombie-game:v0.1:>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
SELECT $this WHERE {
$this zg:xmin ?a; zg:xmax ?b; zg:ymin ?c; zg:ymax ?d. FILTER(?a>=?b || ?c>=?d)
}

PREFIX zg: <urn:zombie-game:v0.1:>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
SELECT $this WHERE {
$this zg:actionDefinition/zg:target_kind ?k. FILTER((?k="Agent" && NOT EXISTS {$this zg:targetStart ?s}) || (?k="Environment" && NOT EXISTS {$this zg:targetEntity ?e}) || (?k="Footprint" && NOT EXISTS {$this zg:footprint ?r}))
}

PREFIX zg: <urn:zombie-game:v0.1:>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
SELECT $this WHERE {
$this zg:quantity ?q; zg:reserved ?r. FILTER(?r>?q)
}

PREFIX zg: <urn:zombie-game:v0.1:>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
SELECT $this WHERE {
$this zg:actionResult ?r; zg:startTime ?s; zg:plannedEnd ?p. OPTIONAL {$this zg:resolvedAt ?e} FILTER((?r=zg:IN_PROGRESS && (BOUND(?e) || EXISTS {$this zg:actorAfterEnd ?a})) || (?r!=zg:IN_PROGRESS && (!BOUND(?e) || NOT EXISTS {$this zg:actorBeforeEnd ?b; zg:actorAfterEnd ?a})) || (BOUND(?e) && ?e<?s) || (?r IN (zg:SUCCEEDED,zg:MISSED) && ?e!=?p))
}

PREFIX zg: <urn:zombie-game:v0.1:>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
SELECT $this WHERE {
$this zg:start_at ?s; zg:end_at ?e. FILTER(?e<?s)
}

PREFIX zg: <urn:zombie-game:v0.1:>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
SELECT $this WHERE {
$this zg:ofAgent ?a; zg:biologicalType ?t; zg:activeRole ?r. ?r zg:ofAgent ?b; zg:roleDefinition/zg:compatibleType ?rt. FILTER(?a!=?b || ?t!=?rt)
}

PREFIX zg: <urn:zombie-game:v0.1:>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
SELECT $this WHERE {
OPTIONAL {$this zg:activeRole/zg:roleDefinition ?role} OPTIONAL {$this zg:spit_charges ?q} FILTER((?role=zg:SPITTER && !BOUND(?q)) || (BOUND(?q) && (!BOUND(?role) || ?role!=zg:SPITTER)) || (BOUND(?q) && EXISTS {zg:SPITTER zg:max_spit_charges ?max FILTER(?q>?max)}))
}

PREFIX zg: <urn:zombie-game:v0.1:>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
SELECT $this WHERE {
$this zg:activeRole/zg:roleDefinition ?role. ?role ?p ?value. FILTER(?p IN (zg:base_speed,zg:base_sense_r,zg:base_damage_resistance,zg:medical_skill,zg:combat_skill,zg:melee_damage,zg:carry_capacity,zg:claw_damage,zg:attack_skill)) FILTER(NOT EXISTS {$this ?p ?value})
}

PREFIX zg: <urn:zombie-game:v0.1:>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
SELECT $this WHERE {
$this zg:hunger ?h; zg:life ?l. FILTER((?h=100 && ?l>0 && NOT EXISTS {$this zg:starvation_started_at ?s; zg:next_starvation_damage_at ?n}) || ((?h<100 || ?l=0) && (EXISTS {$this zg:starvation_started_at ?s} || EXISTS {$this zg:next_starvation_damage_at ?n})))
}

PREFIX zg: <urn:zombie-game:v0.1:>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
SELECT $this WHERE {
$this zg:ofAgent ?a; zg:atTime ?t; zg:revision ?r. ?other a zg:AgentState; zg:ofAgent ?a; zg:atTime ?t; zg:revision ?r. FILTER(?other!=$this)
}

PREFIX zg: <urn:zombie-game:v0.1:>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
SELECT $this WHERE {
$this zg:biologicalType ?t; zg:status ?s; zg:life ?l. FILTER((?l=0 && ?s!=zg:DEAD) || (?l>0 && ?s=zg:DEAD) || (?t=zg:Human && ?s=zg:ACTIVE) || (?t=zg:Zombie && ?s NOT IN (zg:ACTIVE,zg:DEAD)) || (?s=zg:INFECTED && NOT EXISTS {$this zg:activeEpisode ?e}) || (?s!=zg:INFECTED && EXISTS {$this zg:activeEpisode ?e}))
}

PREFIX zg: <urn:zombie-game:v0.1:>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
SELECT $this WHERE {
$this zg:biologicalType ?t. FILTER((?t=zg:Human && NOT EXISTS {$this a zg:HumanState; zg:hunger ?h; zg:inventory ?i}) || (?t=zg:Zombie && NOT EXISTS {$this a zg:ZombieState; zg:virulence ?v}) || (?t=zg:Zombie && EXISTS {$this zg:inventory ?i}) || (?t=zg:Zombie && EXISTS {$this zg:hunger ?h}))
}

PREFIX zg: <urn:zombie-game:v0.1:>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
SELECT $this WHERE {
$this zg:ofAgent/zg:inRun/zg:world ?w; zg:world ?v. FILTER(?w!=?v)
}

PREFIX zg: <urn:zombie-game:v0.1:>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
